def affineHemisphereRealization (pole : sphere (0 : V) 1) (n : ℕ) :
    AffineRationalChains V n →ₗ[ℚ] RawRationalChains (closedHemisphere pole) n :=
  Finsupp.lmapDomain ℚ ℚ (affineHemisphereSimplex pole)

